      backup_text =
        "# ARCANE CALCULATOR #\n\
         # Expression parser and evaluator with operator precedence #\n\n\
         type Token =\n\
         + TNum(Int)\n\
         + TPlus\n\
         + TMinus\n\
         + TStar\n\
         + TSlash\n\
         + TLParen\n\
         + TRParen\n\
         + TEnd\n\
         in\n\n\
         type Expr =\n\
         + Num(Int)\n\
         + Add(Expr, Expr)\n\
         + Sub(Expr, Expr)\n\
         + Mul(Expr, Expr)\n\
         + Div(Expr, Expr)\n\
         + Neg(Expr)\n\
         in\n\n\
         let isDigit : String -> Bool =\n\
         fun c ->\n\
         c $== \"0\" || c $== \"1\" || c $== \"2\" || c $== \"3\" || c $== \
         \"4\" ||\n\
         c $== \"5\" || c $== \"6\" || c $== \"7\" || c $== \"8\" || c $== \"9\"\n\
         in\n\n\
         let isSpace : String -> Bool =\n\
         fun c -> c $== \" \"\n\
         in\n\n\
         let charToDigit : String -> Int =\n\
         fun c ->\n\
         if c $== \"0\" then 0\n\
         else if c $== \"1\" then 1\n\
         else if c $== \"2\" then 2\n\
         else if c $== \"3\" then 3\n\
         else if c $== \"4\" then 4\n\
         else if c $== \"5\" then 5\n\
         else if c $== \"6\" then 6\n\
         else if c $== \"7\" then 7\n\
         else if c $== \"8\" then 8\n\
         else 9\n\
         in\n\n\
         let charAt : (String, Int) -> String =\n\
         fun (s, i) ->\n\
         if i < 0 || i >= string_length(s) then \"\"\n\
         else string_sub(s, i, 1)\n\
         in\n\n\
         let parseNumber : (String, Int) -> (Int, Int) =\n\
         fun (s, pos) ->\n\
         let helper : (Int, Int) -> (Int, Int) = fun (acc, i) ->\n\
         let c = charAt(s, i) in\n\
         if isDigit(c)\n\
         then helper(acc * 10 + charToDigit(c), i + 1)\n\
         else (acc, i)\n\
         in\n\
         helper(0, pos)\n\
         in\n\n\
         let skipSpaces : (String, Int) -> Int =\n\
         fun (s, pos) ->\n\
         let helper : Int -> Int = fun i ->\n\
         if isSpace(charAt(s, i))\n\
         then helper(i + 1)\n\
         else i\n\
         in\n\
         helper(pos)\n\
         in\n\n\
         let tokenize : String -> [Token] =\n\
         fun input ->\n\
         let helper : Int -> [Token] = fun pos ->\n\
         let i = skipSpaces(input, pos) in\n\
         let c = charAt(input, i) in\n\
         if c $== \"\" then [TEnd]\n\
         else if isDigit(c) then\n\
         let (num, nextPos) = parseNumber(input, i) in\n\
         TNum(num) :: helper(nextPos)\n\
         else if c $== \"+\" then TPlus :: helper(i + 1)\n\
         else if c $== \"-\" then TMinus :: helper(i + 1)\n\
         else if c $== \"*\" then TStar :: helper(i + 1)\n\
         else if c $== \"/\" then TSlash :: helper(i + 1)\n\
         else if c $== \"(\" then TLParen :: helper(i + 1)\n\
         else if c $== \")\" then TRParen :: helper(i + 1)\n\
         else helper(i + 1)\n\
         in\n\
         helper(0)\n\
         in\n\n\
         type ParseResult = (Expr, [Token]) in\n\n\
         # Parser with recursive descent and operator precedence #\n\
         let (parseExpr : [Token] -> ParseResult,\n\
         parseTerm : [Token] -> ParseResult,\n\
         parseFactor : [Token] -> ParseResult,\n\
         parseAtom : [Token] -> ParseResult) = (\n\n\
         fun tokens ->\n\
         let (left, rest) = parseTerm(tokens) in\n\
         let loop : (Expr, [Token]) -> ParseResult = fun (acc, toks) ->\n\
         case toks\n\
         | TPlus :: tail =>\n\
         let (right, rest2) = parseTerm(tail) in\n\
         loop(Add(acc, right), rest2)\n\
         | TMinus :: tail =>\n\
         let (right, rest2) = parseTerm(tail) in\n\
         loop(Sub(acc, right), rest2)\n\
         | _ => (acc, toks)\n\
         end\n\
         in\n\
         loop(left, rest),\n\n\
         fun tokens ->\n\
         let (left, rest) = parseFactor(tokens) in\n\
         let loop : (Expr, [Token]) -> ParseResult = fun (acc, toks) ->\n\
         case toks\n\
         | TStar :: tail =>\n\
         let (right, rest2) = parseFactor(tail) in\n\
         loop(Mul(acc, right), rest2)\n\
         | TSlash :: tail =>\n\
         let (right, rest2) = parseFactor(tail) in\n\
         loop(Div(acc, right), rest2)\n\
         | _ => (acc, toks)\n\
         end\n\
         in\n\
         loop(left, rest),\n\n\
         fun tokens ->\n\
         case tokens\n\
         | TMinus :: tail =>\n\
         let (inner, rest) = parseFactor(tail) in\n\
         (Neg(inner), rest)\n\
         | _ => parseAtom(tokens)\n\
         end,\n\n\
         fun tokens ->\n\
         case tokens\n\
         | TNum(n) :: tail => (Num(n), tail)\n\
         | TLParen :: tail =>\n\
         let (inner, rest) = parseExpr(tail) in\n\
         case rest\n\
         | TRParen :: tail2 => (inner, tail2)\n\
         | _ => (inner, rest)\n\
         end\n\
         | _ => (Num(0), tokens)\n\
         end\n\
         )\n\
         in\n\n\
         let parse : String -> Expr =\n\
         fun input ->\n\
         let tokens = tokenize(input) in\n\
         let (ast, _) = parseExpr(tokens) in\n\
         ast\n\
         in\n\n\
         let evaluate : Expr -> Int =\n\
         fun e ->\n\
         case e\n\
         | Num(n) => n\n\
         | Add(a, b) => evaluate(a) + evaluate(b)\n\
         | Sub(a, b) => evaluate(a) - evaluate(b)\n\
         | Mul(a, b) => evaluate(a) * evaluate(b)\n\
         | Div(a, b) =>\n\
         let divisor = evaluate(b) in\n\
         if divisor == 0 then 0 else evaluate(a) / divisor\n\
         | Neg(a) => 0 - evaluate(a)\n\
         end\n\
         in\n\n\
         let calculate : String -> Int =\n\
         fun input -> evaluate(parse(input))\n\
         in\n\n\
         hint \"single digit\"\n\
         test calculate(\"5\") == 5 end;\n\n\
         hint \"multi-digit number\"\n\
         test calculate(\"123\") == 123 end;\n\n\
         hint \"number with spaces\"\n\
         test calculate(\"  42  \") == 42 end;\n\n\
         hint \"simple addition\"\n\
         test calculate(\"2 + 3\") == 5 end;\n\n\
         hint \"simple subtraction\"\n\
         test calculate(\"10 - 4\") == 6 end;\n\n\
         hint \"simple multiplication\"\n\
         test calculate(\"3 * 4\") == 12 end;\n\n\
         hint \"simple division\"\n\
         test calculate(\"20 / 5\") == 4 end;\n\n\
         hint \"multiplication before addition\"\n\
         test calculate(\"2 + 3 * 4\") == 14 end;\n\n\
         hint \"multiplication before subtraction\"\n\
         test calculate(\"10 - 2 * 3\") == 4 end;\n\n\
         hint \"division before addition\"\n\
         test calculate(\"1 + 8 / 2\") == 5 end;\n\n\
         hint \"mixed precedence\"\n\
         test calculate(\"2 * 3 + 4 * 5\") == 26 end;\n\n\
         hint \"subtraction is left associative\"\n\
         test calculate(\"10 - 5 - 2\") == 3 end;\n\n\
         hint \"division is left associative\"\n\
         test calculate(\"24 / 4 / 2\") == 3 end;\n\n\
         hint \"addition is left associative\"\n\
         test calculate(\"1 + 2 + 3\") == 6 end;\n\n\
         hint \"parentheses override precedence\"\n\
         test calculate(\"(2 + 3) * 4\") == 20 end;\n\n\
         hint \"nested parentheses\"\n\
         test calculate(\"((2 + 3))\") == 5 end;\n\n\
         hint \"complex parentheses\"\n\
         test calculate(\"(1 + 2) * (3 + 4)\") == 21 end;\n\n\
         hint \"parentheses in middle\"\n\
         test calculate(\"2 * (3 + 4) * 5\") == 70 end;\n\n\
         hint \"unary minus\"\n\
         test calculate(\"-5\") == -5 end;\n\n\
         hint \"unary minus in expression\"\n\
         test calculate(\"3 + -2\") == 1 end;\n\n\
         hint \"unary minus with parentheses\"\n\
         test calculate(\"-(3 + 2)\") == -5 end;\n\n\
         hint \"double negative\"\n\
         test calculate(\"--5\") == 5 end;\n\n\
         hint \"complex expression 1\"\n\
         test calculate(\"1 + 2 * 3 - 4 / 2\") == 5 end;\n\n\
         hint \"complex expression 2\"\n\
         test calculate(\"(1 + 2) * (3 - 4) / (5 + 6)\") == 0 end;\n\n\
         hint \"complex expression 3\"\n\
         test calculate(\"10 - 3 * 2 + 8 / 4\") == 6 end;\n\n\
         hint \"zero\"\n\
         test calculate(\"0\") == 0 end;\n\n\
         hint \"division by zero returns 0\"\n\
         test calculate(\"5 / 0\") == 0 end;\n\n\
         hint \"multiply by zero\"\n\
         test calculate(\"100 * 0\") == 0 end;\n\n\
         (\n\
         calculate(\"2 + 3 * 4\"),\n\
         calculate(\"(2 + 3) * 4\"),\n\
         calculate(\"10 - 5 - 2\")\n\
         )\n";
      refractors = "()";
    } )
